


# Visualise Tajima's D, pi, and Fst for AM pop2 and pop5 (MSL0 vs MSL4) on chr31
# Data generated by: population_statistics_and_fst2.R (50kb windows, 1kb Fst windows)




# 1. SETUP ---------------------------------------------------------------------

library(tidyverse)
library(patchwork)

# Colours (Paul Tol colour-blind palette)
col_msl0 <- "#BB5566"  # Rose/red — MSL0 (deletion present)
col_msl4 <- "#004488"  # Dark blue — MSL4 (deletion absent)

# Base directory — change if needed
base_dir <- "/home/johansson/Documents/Bioinformatics/Leishmania/Leishmania Manuscript"
data_dir <- file.path(base_dir, "Data/Population Diversity and Differentiation")
fig_dir  <- file.path(base_dir, "Figures/Population Diversity and Differentiation")
dir.create(fig_dir, showWarnings = FALSE, recursive = TRUE)

# MSL locus coordinates on chr31 (from MSL-genes-only.bed)
msl_start <- 1181282
msl_end   <- 1192406




# 2. LOAD DATA -----------------------------------------------------------------

# Helper function to load pi files
load_pi <- function(path, pop, msl) {
  read_tsv(path, show_col_types = FALSE) %>%
    mutate(
      midpoint = (BIN_START + BIN_END) / 2,
      population = pop,
      msl_group = msl
    )
}

# Helper function to load Tajima's D files
load_tajd <- function(path, pop, msl) {
  read_tsv(path, show_col_types = FALSE) %>%
    mutate(
      midpoint = BIN_START + 25000,  # 50kb window midpoint
      population = pop,
      msl_group = msl
    ) %>%
    filter(!is.nan(TajimaD))
}

# Helper function to load Fst files
load_fst <- function(path, pop) {
  read_tsv(path, show_col_types = FALSE) %>%
    mutate(
      midpoint = (BIN_START + BIN_END) / 2,
      population = pop
    ) %>%
    filter(!is.nan(WEIGHTED_FST), WEIGHTED_FST >= 0)
}

# Pi files
pi_pop2_msl0 <- load_pi(
