  "Pop2", "MSL4"
)
pi_pop5_msl0 <- load_pi(
  file.path(data_dir, "pop_5__Americas.K13.pop5.MSL0.diploidised.sample_names.txt__tetraploid_freebayes_regenotyped_sorted_LinJ.31_2025-07-01.filtered_2026-04-07.diploidised.vcf.gz.windowed.pi"),
