# 3. SHARED THEME --------------------------------------------------------------

theme_pop <- function() {
  theme_bw() +
    theme(
      panel.grid.minor   = element_blank(),
      panel.grid.major.x = element_blank(),
      axis.text          = element_text(size = 11),
      axis.title         = element_text(size = 12),
      legend.title       = element_text(size = 12, face = "bold"),
      legend.text        = element_text(size = 11),
      legend.position    = "right",
      plot.title         = element_text(size = 13, face = "bold", hjust = 0.5),
      plot.title.position = "plot",
      strip.text         = element_text(size = 11)
    )
}

# MSL locus shading layer — widened to 100kb either side for visibility at chr31 scale
msl_shade <- annotate(
  "rect",
  xmin = msl_start - 100000, xmax = msl_end + 100000,
  ymin = -Inf, ymax = Inf,
  fill = "#CCCCCC", alpha = 0.4
)

# Colour scale
msl_colours <- scale_colour_manual(
  name   = "MSL group",
  values = c("MSL0" = col_msl0, "MSL4" = col_msl4),
  labels = c("MSL0 (deletion present)", "MSL4 (deletion absent)")
)




# 4. PLOTTING FUNCTION ---------------------------------------------------------

make_figure <- function(tajd_data, pi_data, fst_data, pop_label, pop_note) {
  
  x_lab <- "Position on chr31 (bp)"
  
  # Tajima's D panel
  p_tajd <- ggplot(tajd_data, aes(x = midpoint, y = TajimaD, colour = msl_group)) +
    msl_shade +
    geom_hline(yintercept = 0, linetype = "dashed", colour = "grey50", linewidth = 0.4) +
    geom_line(linewidth = 0.7, alpha = 0.85) +
    geom_point(size = 1.5, alpha = 0.7) +
    msl_colours +
    labs(
      title = paste0(pop_label, " — Tajima's D across chr31\n", pop_note),
      x = NULL,
      y = "Tajima's D"
    ) +
    theme_pop()
  
  # Pi panel
  p_pi <- ggplot(pi_data, aes(x = midpoint, y = PI, colour = msl_group)) +
    msl_shade +
    geom_line(linewidth = 0.7, alpha = 0.85) +
    geom_point(size = 1.5, alpha = 0.7) +
    msl_colours +
    labs(
      x = NULL,
      y = expression(paste("Nucleotide diversity (", pi, ")"))
    ) +
    theme_pop()
  
  # Fst panel — loess smoothed only (1kb raw windows too noisy to plot)
  p_fst <- ggplot(fst_data, aes(x = midpoint, y = WEIGHTED_FST)) +
    msl_shade +
    geom_hline(yintercept = 0, linetype = "dashed", colour = "grey50", linewidth = 0.4) +
    geom_smooth(method = "loess", span = 0.15, se = TRUE,
                colour = "#CC3311", fill = "#CC3311", alpha = 0.15, linewidth = 0.9) +
    labs(
      x = x_lab,
      y = expression(F[ST])
    ) +
    theme_pop()
  
  # Combine with patchwork
  p_tajd / p_pi / p_fst +
    plot_layout(heights = c(1.2, 1, 0.8), guides = "collect") &
    theme(legend.position = "right")
}




# 5. BUILD FIGURES -------------------------------------------------------------

fig_pop2 <- make_figure(
  tajd_data  = tajd_pop2,
  pi_data    = pi_pop2,
  fst_data   = fst_pop2,
  pop_label  = "AM Population 2 (MSL0 n=24, MSL4 n=46)",
  pop_note   = "50kb windows | Grey shading = MSL locus ±100kb (chr31: 1,181,282–1,192,406)"
)

fig_pop5 <- make_figure(
