  pi_data    = pi_pop5,
  fst_data   = fst_pop5,
  pop_label  = "AM Population 5 (MSL0 n=18, MSL4 n=2)",
  pop_note   = "50kb windows | Grey shading = MSL locus ±100kb | CAVEAT: MSL4 n=2"
)




